-- Table: transaction_purchase_return_detail
-- Source: accounting_admin_db.sql (4. Purchasing flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_purchase_return_detail (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    purchase_return_id      BIGINT NOT NULL REFERENCES transaction_purchase_return(id) ON DELETE CASCADE,
    line_number             INTEGER NOT NULL CHECK (line_number > 0),
    purchase_invoice_detail_id BIGINT REFERENCES transaction_purchase_invoice_detail(id),
    product_id              BIGINT NOT NULL REFERENCES masterdata_product(id),
    description             TEXT,
    quantity                NUMERIC(18,4) NOT NULL CHECK (quantity > 0),
    uom_id                  BIGINT NOT NULL REFERENCES masterdata_uom(id),
    unit_cost               NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
    tax_rate_id             BIGINT REFERENCES masterdata_tax_rate(id),
    tax_amount              NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    total                   NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    action                  VARCHAR(30) NOT NULL DEFAULT 'return_to_supplier'
                            CHECK (action IN ('return_to_supplier', 'scrap')),
    UNIQUE (purchase_return_id, line_number)
);
